import numpy as np

def gini(counts):
    p = np.asarray(counts) / sum(counts)
    return 1 - (p ** 2).sum()

def entropy(counts):
    p = np.asarray(counts)
    p = p[p > 0] / p.sum()
    return -(p * np.log2(p)).sum()

# de node uit het voorbeeld: 20 samples, 12/8 -> kinderen 2/6 en 10/2
ouder, links, rechts = (12, 8), (2, 6), (10, 2)

for naam, f in [('gini', gini), ('entropy', entropy)]:
    gewogen = (sum(links) * f(links) + sum(rechts) * f(rechts)) / sum(ouder)
    print(f'{naam:8s} ouder={f(ouder):.3f}  kinderen={gewogen:.3f}  '
          f'informatiewinst={f(ouder) - gewogen:.3f}')
